func jrndUint(r *rand.Rand, max uint64) uint64 {
	switch r.Intn(4) {
	case 0:
		return 0
	case 1:
		return max
	case 2:
		if x := uint64(r.Intn(20)); x <= max {
			return x
		}
		return max
	}
	return r.Uint64() % (max/2 + 1)
}

