// TestJSONDecode: the codec decodes the encodings of every listed type, and mutations of them,
// into every decodable type (fresh and pre-filled targets) as real encoding/json does; it panics
// only into a non-nil slice (pre-filled slice targets are left out; a struct's slice field may
// be non-nil).
func TestJSONDecode(t *testing.T) {
	r := rand.New(rand.NewSource(2))
	samples := jsonSamples(r, 200)
	targets := jsonTargets()
	nSlice := 0
	for it := 0; it < 20000; it++ {
		data := samples[r.Intn(len(samples))]
		for m := r.Intn(3); m > 0; m-- {
			data = jsonMutate(r, data, samples)
		}
		tg := targets[r.Intn(len(targets))]
		a, b := tg.new(r, r.Intn(2) == 0)
		if !jsonCheckDecode(t, tg.name, data, a, b) {
			nSlice++
		}
	}
	if nSlice > 10000 {
		t.Fatalf("%d of 20000 decodings into a non-nil slice (the model panics): too few checked", nSlice)
	}
}

// TestJSONScan: the scanner agrees with real encoding/json on what is one valid value (random
// texts over JSON's structural characters and a plain alphabet), and a stream of encodings
// separated by newlines (Encoder's) splits as real encoding/json's Decoder splits it, at every
// cut (More before a value's last byte).
func TestJSONScan(t *testing.T) {
	r := rand.New(rand.NewSource(3))
	const alpha = "{}[],:\" \n\t0123-.eE+tfrulnasx"
	for it := 0; it < 200000; it++ {
		n := r.Intn(12)
		b := make([]byte, n)
		for i := range b {
			b[i] = alpha[r.Intn(len(alpha))]
		}
		if got, want := jsoncodec.Valid(b), json.Valid(b); got != want {
			t.Fatalf("Valid(%q): scanner %v, real %v", b, got, want)
		}
	}
	samples := jsonSamples(r, 300)
	for _, s := range samples {
		if !jsoncodec.Valid(s) {
			t.Fatalf("Valid(%q) false", s)
		}
		stream := append(append([]byte{}, s...), '\n')
		for cut := 0; cut <= len(stream); cut++ {
			st, end := jsoncodec.Scan(stream[:cut], false)
			if cut < len(s) && st != jsoncodec.More {
				if !(st == jsoncodec.Done && s[0] != '{' && s[0] != '[' && s[0] != '"' && uint64(cut) >= end) {
					t.Fatalf("Scan(%q, false) = %d, %d, want More", stream[:cut], st, end)
				}
			}
			if cut > len(s) && (st != jsoncodec.Done || end != uint64(len(s))) {
				t.Fatalf("Scan(%q, false) = %d, %d, want Done, %d", stream[:cut], st, end, len(s))
			}
		}
		// a suffix of a stream of two values: real Decoder's first value or error, and the
		// scanner's
		t2 := samples[r.Intn(len(samples))]
		both := append(append(append(append([]byte{}, s...), '\n'), t2...), '\n')
		for k := 0; k <= len(both); k++ {
			jsonCheckStream(t, both[k:])
		}
	}
}

// jsonCheckStream: real Decoder's first Decode on b (all of it available, then EOF) succeeds
// or fails with a syntax error, io.EOF or io.ErrUnexpectedEOF exactly when the scanner says,
// and the value it decodes is the scanner's.
func jsonCheckStream(t *testing.T, b []byte) {
	t.Helper()
	var raw json.RawMessage
	err := json.NewDecoder(strings.NewReader(string(b))).Decode(&raw)
	st, end := jsoncodec.Scan(b, true)
	switch {
	case err == nil:
		if st != jsoncodec.Done || strings.TrimSpace(string(b[:end])) != string(raw) {
			t.Fatalf("stream %q: real decodes %q, scanner %d, %d", b, raw, st, end)
		}
	case err.Error() == "EOF" || err.Error() == "unexpected EOF":
		if st != jsoncodec.More {
			t.Fatalf("stream %q: real %v, scanner %d, %d", b, err, st, end)
		}
		if (err.Error() == "EOF") != (strings.TrimSpace(string(b)) == "") {
			t.Fatalf("stream %q: real %v", b, err)
		}
	default:
		if st != jsoncodec.Bad {
			t.Fatalf("stream %q: real %v, scanner %d, %d", b, err, st, end)
		}
	}
}

